def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    if history[0][1] == 'D':
        return 'D'
    first_def = -1
    for i in range(1, n):
        if history[i][1] == 'D':
            first_def = i
            break
    if first_def == -1:
        return 'D'
    if n - first_def <= 2:
        return 'C'
    if n >= 2 and history[-1][1] == 'D' and history[-2][1] == 'D':
        return 'D'
    return 'C'
